function noodleMetrics(){return `<div class="noodle-metrics"><div><strong>12.8<span>万</span></strong><p>抖音代表图文浏览量</p><small>抖音 · 广州树下茶屋</small></div><div><strong>2,338</strong><p>抖音代表图文收藏</p><small>抖音 · 同篇作品最新截图</small></div><div><strong>16<span>次</span></strong><p>完成置换合作</p><small>全部为置换 · 非现金商单</small></div><div><strong>0</strong><p>付费投流</p><small>运营期间 · 本人提供</small></div></div>`;}
function noodleAccounts(){return `<div class="noodle-accounts"><a href="https://v.douyin.com/UU_aWDICxOw/" target="_blank" rel="noopener noreferrer"><span class="mono">DOUYIN / 抖音 ↗</span><h3>🍜noodle</h3><p>2.3 万获赞 · 386 粉丝</p><small>抖音号 81172546974</small></a><a href="https://xhslink.cn/o/86eW9P7y7TJ" target="_blank" rel="noopener noreferrer"><span class="mono">RED / 小红书 ↗</span><h3>noodle🍜</h3><p>4614 获赞与收藏 · 51 粉丝</p><small>小红书号 95018585241</small></a></div><p class="noodle-source">以上为提供的主页截图时累计数据，非实时数据，也非运营期新增数据。两个平台的互动口径不同，分别展示。查看主页可能需要登录平台或打开 App。</p>`;}
function noodleOverview(project){const v=caseVisuals.noodle;return `<section class="case-thesis"><div class="thesis-marker"><span class="mono">INDEPENDENT CREATOR / 个人账号运营</span><span aria-hidden="true">↗</span></div><h3>${v.statement}</h3><div class="thesis-rule" aria-hidden="true"><i></i><span>2025.12 — 2026.05</span><i></i></div></section>${noodleMetrics()}${noodleAccounts()}<div class="case-contactsheet">${v.images.map(([file,caption])=>`<figure><button class="image-button" data-image="media/${file}" data-caption="${caption} · 个人账号作品" aria-label="查看${caption}"><img src="media/${file}" alt="${caption}" loading="lazy"></button><figcaption>${caption}</figcaption></figure>`).join('')}</div><div class="case-process"><div class="process-heading"><span class="mono">PROCESS / 从兴趣到运营</span><span aria-hidden="true">＋</span></div>${project.steps.map(([h,p],i)=>`<section class="case-step"><span class="step-index">0${i+1}</span><h3>${h}</h3><p>${p}</p></section>`).join('')}</div><aside class="case-note"><span class="mono">DATA NOTE / 数据说明</span><p>${project.note}</p></aside><button class="view-material" data-view-material><span>查看代表内容与复盘</span><span class="mono">CONTENT / INSIGHT</span><span aria-hidden="true">↗</span></button>`;}
