function noodleProfiles(card=false){return `<div class="noodle-profile-pair">${[['noodle-profile-douyin','抖音 / DOUYIN','https://v.douyin.com/UU_aWDICxOw/','抖音'],['noodle-profile-red','小红书 / RED','https://xhslink.cn/o/86eW9P7y7TJ','小红书']].map(([file,label,url,platform])=>card?`<span class="noodle-profile-mini"><span>${label}</span><span class="noodle-profile-viewport"><img src="media/${file}.jpg" alt="${label}个人账号首页" loading="lazy"></span></span>`:`<figure><figcaption>${label}</figcaption><a class="case-cover-image noodle-profile-link" href="${url}" target="_blank" rel="noopener noreferrer" aria-label="查看${platform}账号主页（新窗口）"><span class="noodle-profile-viewport"><img src="media/${file}.jpg" alt="${label} · noodle 个人账号首页截图"></span><span class="noodle-profile-cta">查看${platform}主页 <span aria-hidden="true">↗</span></span></a></figure>`).join('')}</div>`;}
function noodleStudyGroup(platform){const label=platform==='douyin'?'抖音':'小红书';return `<section class="noodle-platform" data-platform="${platform}"><div class="noodle-platform-heading"><span>${platform==='douyin'?'DOUYIN':'RED'}</span><h3>${label} · 三篇代表作</h3><p>平台独立统计 / 本次提供的作品截图</p></div><div class="noodle-studies">${noodleStudies[platform].map((item,i)=>`<article class="noodle-study"><figure><button class="image-button noodle-evidence" data-image="media/${item.file}.jpg" data-caption="${label} · ${item.title} · 作品数据截图" aria-label="放大${label}作品数据截图"><img src="media/${item.file}.jpg" alt="${label} · ${item.title} · 作品数据截图" loading="lazy"></button><figcaption>${label}原始截图 · 点击查看大图 ↗</figcaption>${item.viewEvidence?`<button class="noodle-proof-link" data-image="media/${item.viewEvidence}.jpg" data-caption="${label} · ${item.title} · ${item.views} 浏览截图">查看浏览量截图 ↗</button>`:''}</figure><div class="noodle-study-copy"><span class="noodle-platform-badge">${label} / 0${i+1} / ${item.tag}</span><h3>${item.title}</h3><div class="noodle-result"><strong>${item.views?item.views+' 浏览':item.likes+' 点赞'}</strong><span>${item.likes} 赞 · ${item.comments} 评论 · ${item.saves} 收藏${item.shares?' · '+item.shares+' 分享':''}</span></div><p>${item.body}</p><small>数据以本次提供的${label}截图为准，非实时数据。${item.views?'':'本张截图未显示浏览量，仅展示可见互动数据。'}</small></div></article>`).join('')}</div></section>`;}
function noodleMaterials(){return heading('双平台代表内容','个人账号 · 独立运营')+`<p class="noodle-source">抖音与小红书分别展示，每个平台各三篇。以下数据取自本次提供的作品截图；同主题内容在不同平台独立统计，不合并浏览或互动。</p>`+noodleStudyGroup('douyin')+noodleStudyGroup('red')+
 heading('受众与内容判断','阶段复盘 · 粉丝画像')+`<div class="noodle-audience"><div><strong>92%</strong><span>广东地区</span><p>在本地探店选题中，重视城市与到达信息。</p></div><div><strong>47%</strong><span>18—23 岁</span><p>围绕年轻人的周末出游与小店探索组织内容。</p></div><div><strong>86%</strong><span>女性</span><p>记录当时的粉丝构成，作为后续选题观察依据。</p></div></div><p class="noodle-source">数据来自阶段复盘第 4 页；为当时粉丝画像，不代表两个平台合计，也不用于推断消费能力或实际到店转化。</p>`+
 heading('置换合作实践','独立完成 · 非现金合作')+`<section class="noodle-cooperation"><div><span class="mono">BARTER COLLABORATIONS</span><strong>16<span> 次</span></strong><p>全部为置换合作</p></div><div><h3>从个人分享，到合作内容交付。</h3><p>在账号运营过程中承接探店置换合作，个人完成内容选题、拍摄、修图、文案与发布。累计含置换权益的总价值为 <b>2000+</b>，不作为现金收入展示。</p><p class="noodle-source">合作数量、性质与价值由本人确认；代表图文的浏览与收藏数据不直接归因于合作，也不等同于商家销售或到店成果。</p></div></section>`+`<figure class="noodle-collaboration-evidence"><div><span class="mono">COLLABORATION ARCHIVE / 合作材料</span><h3>邀约与 Brief，记录合作的起点。</h3><p>置换邀约、内容要求与品牌沟通材料选集，展示账号收到的合作需求。</p><small>本图为邀约与需求材料；16 次已完成置换及 2000+ 总价值由本人另行确认。</small></div><button class="image-button" data-image="media/noodle-collaborations.jpg" data-caption="noodle · 置换邀约与合作 Brief 选集" aria-label="放大置换邀约与合作 Brief 选集"><img src="media/noodle-collaborations.jpg" alt="noodle 账号收到的置换邀约与合作 Brief 选集" loading="lazy"></button><figcaption>合作材料选集 · 点击查看大图 ↗</figcaption></figure>`+
 heading('复盘后的改进方向','计划与思考 · 非已验证成效')+`<div class="noodle-next"><section><span class="mono">01 / 选题</span><h3>从偶发发现，到持续积累</h3><p>沿新店探索、小众私藏、城市合集三条线建立选题池，减少对单次探店机会的依赖。</p></section><section><span class="mono">02 / 表达</span><h3>让好看，也更好用</h3><p>统一封面和栏目表达；在正文补充位置、预算、适合人群等信息，帮助读者判断是否值得前往。</p></section><section><span class="mono">03 / 复盘</span><h3>从浏览，看到后续行动</h3><p>后续按内容类型观察收藏、主页访问与关注变化，验证哪些表达更能回应用户需求。</p></section></div>`;
}
